// Lantern Race: each tap lights one of your lanterns. Light all seven first to win; when the fuse burns out, whoever
// lit more wins, and a level count is a draw.
import { stationView, type BuiltEvent, type BuiltRules, type Outcome, type Seat, type StationView } from "@egb/sdk";

export const LANTERNS = 7;
export const FUSE_MS = 30_000;
/** A second touch this soon after the last is the same tap bouncing, not a new one. */
export const SETTLE_MS = 150;

export interface LanternState {
  readonly startedAt: number;
  readonly lit: readonly [number, number];
  readonly lastTap: readonly [number | null, number | null];
  readonly over: boolean;
  readonly winner: Seat | null;
}

function burnedOut(state: LanternState): LanternState {
  const [a, b] = state.lit;
  return { ...state, over: true, winner: a === b ? null : a > b ? 0 : 1 };
}

function step(state: LanternState, event: BuiltEvent): LanternState {
  if (state.over) return state;
  if (event.now - state.startedAt >= FUSE_MS) return burnedOut(state);
  if (event.type === "tick") return state;
  const last = state.lastTap[event.seat];
  if (last !== null && event.now - last < SETTLE_MS) return state;
  const lit: [number, number] = [state.lit[0], state.lit[1]];
  lit[event.seat] += 1;
  const lastTap: [number | null, number | null] = [state.lastTap[0], state.lastTap[1]];
  lastTap[event.seat] = event.now;
  const won = lit[event.seat] >= LANTERNS;
  return { ...state, lit, lastTap, over: won, winner: won ? event.seat : null };
}

function view(state: LanternState, seat: Seat): StationView {
  const tag = seat === 0 ? "P1" : "P2";
  const lit = state.lit[seat];
  if (!state.over) return stationView(tag, `${lit}/${LANTERNS}`, "TAP TO LIGHT");
  const big = state.winner === null ? "DRAW" : state.winner === seat ? "WIN" : "LOSE";
  return stationView(tag, big, `${lit} lit`);
}

const rules: BuiltRules<LanternState> = {
  start: (_seed, now) => ({ startedAt: now, lit: [0, 0], lastTap: [null, null], over: false, winner: null }),
  step,
  outcome: (state): Outcome | null => (state.over ? { winner: state.winner } : null),
  stations: (state) => [view(state, 0), view(state, 1)],
};

export default rules;

// Lantern Race's screen: the title on a brass plate, the fuse's seconds on an amber readout, and each player's row of
// seven lanterns on their own side. A tap pops the lantern it lit; the end names the winner on a plate.
import type { FrameEvent, Seat } from "@egb/sdk";
import type { GameScreen } from "@egb/sdk/screen";
import { FUSE_MS, LANTERNS, type LanternState } from "./rules.ts";

const CSS = `
.lr { position: absolute; inset: 0; display: flex; flex-direction: column; align-items: center; justify-content: space-evenly;
  background: radial-gradient(ellipse at 50% 30%, #2d2356, #120c24 70%); color: #f3eaff; font: 700 24px system-ui, sans-serif; }
.lr egb-plate { font-size: 44px; }
.lr egb-seg { font-size: 64px; }
.lr-rows { display: flex; flex-direction: column; gap: 6vh; width: 88%; }
.lr-row { display: flex; align-items: center; gap: 2vw; }
.lr-row.p2 { flex-direction: row-reverse; }
.lr-name { width: 14ch; font-size: 28px; text-transform: uppercase; }
.lr-row.p1 .lr-name { color: #ffd2a3; }
.lr-row.p2 .lr-name { color: #b5f1ff; text-align: right; }
.lr-lanterns { display: flex; flex: 1; justify-content: space-between; }
.lr-row.p2 .lr-lanterns { flex-direction: row-reverse; }
.lr-lantern { width: 7vmin; height: 9vmin; border-radius: 45% 45% 30% 30%; background: #211943; box-shadow: inset 0 0 0 2px #3a2f6b; }
.lr-row.p1 .lr-lantern.on { background: #ff9b3d; box-shadow: 0 0 18px #ff9b3d99; }
.lr-row.p2 .lr-lantern.on { background: #3fd9ff; box-shadow: 0 0 18px #3fd9ff99; }
.lr-verdict { opacity: 0; }
.lr-verdict.shown { opacity: 1; transition: opacity 400ms ease-out; }
`;

function el(doc: Document, tag: string, className: string): HTMLElement {
  const node = doc.createElement(tag);
  node.className = className;
  return node;
}

const screen: GameScreen = {
  mount(root, init) {
    const doc = root.ownerDocument;
    const style = doc.createElement("style");
    style.textContent = CSS;
    const stage = el(doc, "div", "lr");
    const title = doc.createElement("egb-plate");
    title.textContent = init.manifest.title.toUpperCase();
    const fuse = doc.createElement("egb-seg");
    fuse.setAttribute("tone", "amber");
    fuse.setAttribute("digits", "2");
    const rows = el(doc, "div", "lr-rows");
    const lanterns: HTMLElement[][] = [];
    ([0, 1] as const).forEach((seat) => {
      const row = el(doc, "div", `lr-row p${seat + 1}`);
      const name = el(doc, "div", "lr-name");
      name.textContent = init.seats[seat].name ?? `Player ${seat + 1}`;
      const strip = el(doc, "div", "lr-lanterns");
      lanterns[seat] = Array.from({ length: LANTERNS }, () => strip.appendChild(el(doc, "div", "lr-lantern")));
      row.append(name, strip);
      rows.append(row);
    });
    const verdict = doc.createElement("egb-plate");
    verdict.className = "lr-verdict";
    stage.append(title, fuse, rows, verdict);
    root.append(style, stage);

    const offset = Date.now() - init.now;
    let state = init.state as LanternState;
    const secondsLeft = () => Math.max(0, Math.ceil((state.startedAt + FUSE_MS - (Date.now() - offset)) / 1000));
    let shown = -1;
    const tickFuse = () => {
      const s = state.over ? 0 : secondsLeft();
      if (s !== shown) fuse.setAttribute("value", String((shown = s)));
    };
    const timer = setInterval(tickFuse, 250);

    const pop = (seat: Seat) => {
      const lantern = lanterns[seat]?.[state.lit[seat] - 1];
      if (lantern && !init.calm) lantern.animate([{ transform: "scale(1.35)" }, { transform: "scale(1)" }], { duration: 260, easing: "ease-out" });
    };
    const draw = (event: FrameEvent) => {
      lanterns.forEach((row, seat) => row.forEach((lantern, i) => lantern.classList.toggle("on", i < (state.lit[seat] ?? 0))));
      if (event.type === "tap") pop(event.seat);
      if (state.over) {
        clearInterval(timer);
        verdict.textContent = state.winner === null ? "A DRAW" : `${(init.seats[state.winner].name ?? `PLAYER ${state.winner + 1}`).toUpperCase()} WINS`;
        verdict.classList.add("shown");
      }
      tickFuse();
    };
    draw({ type: "init" });

    return {
      update(message) {
        state = message.state as LanternState;
        draw(message.event);
      },
    };
  },
};

export default screen;
